import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { FileService } from '../../core/services/file.service';
import { ProfService } from '../../core/services/prof.service';

@Component({
  selector: 'app-prof-public',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './prof-public.component.html',
  styleUrls: ['./prof-public.component.scss']
})
export class ProfPublicComponent implements OnInit {
  slug = '';
  profName = '';
  classes: any[] = [];
  cahiers: any[] = [];

  selectedClassId: number | null = null;
  selectedFile: File | null = null;
  fileName = ''; // 👈 utilisé pour affichage seulement
  uploading = false;

  constructor(
    private route: ActivatedRoute,
    private fileService: FileService,
    private profService: ProfService
  ) {}

  ngOnInit() {
    this.slug = this.route.snapshot.paramMap.get('slug') || '';
    this.profName = this.slug
      .split('-')
      .map(s => s.charAt(0).toUpperCase() + s.slice(1))
      .join(' ');
    this.loadClasses();
  }

  loadClasses() {
    this.profService.getMyClasses().subscribe({
      next: data => (this.classes = data || []),
      error: err => console.error('Erreur chargement classes:', err)
    });
  }

  loadCahiers() {
    if (!this.selectedClassId) {
      this.cahiers = [];
      return;
    }

    this.fileService.getCahiersByClass(this.selectedClassId).subscribe({
      next: res => {
        this.cahiers = (res || []).sort(
          (a: any, b: any) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
      },
      error: err => console.error('Erreur chargement cahiers:', err)
    });
  }

  onFileSelected(event: any) {
    this.selectedFile = event.target.files[0];
  }

  uploadCahier() {
    if (!this.selectedFile || !this.selectedClassId) {
      alert('Veuillez choisir une classe et un fichier.');
      return;
    }

    this.uploading = true;
    this.fileService
      .uploadCahierPedagogique(this.selectedFile, this.selectedClassId)
      .subscribe({
        next: () => {
          // 🧠 Ajout virtuel pour affichage avec ton nom tapé
          this.cahiers.unshift({
            fileName: this.fileName || this.selectedFile?.name,
            fileUrl: URL.createObjectURL(this.selectedFile!),
            createdAt: new Date(),
          });

          this.fileName = '';
          this.selectedFile = null;
          this.uploading = false;
        },
        error: err => {
          console.error('Erreur upload:', err);
          this.uploading = false;
        },
      });
  }
}
<div class="public-container container py-5">
  <div class="text-center mb-5">
    <h1 class="fw-bold text-primary">{{ profName }}</h1>
    <p class="text-muted">📖 Cahiers pédagogiques par classe</p>
  </div>

  <div *ngIf="classes.length > 0; else noClasses">
    <div *ngFor="let c of classes" class="card mb-4 shadow-sm">
      <div class="card-body">
        <h4 class="fw-bold mb-3">{{ c.name }}</h4>

        <ng-container *ngIf="c.cahier; else uploadBlock">
          <p class="text-muted small mb-2">
            <i class="bi bi-calendar-event me-1"></i>
            Mis à jour le {{ c.cahier.createdAt | date: 'dd MMM yyyy, HH:mm' }}
          </p>

          <a [href]="c.cahier.fileUrl" target="_blank" class="btn btn-outline-primary btn-sm">
            <i class="bi bi-download me-1"></i> Télécharger le cahier
          </a>
        </ng-container>

        <ng-template #uploadBlock>
          <div>
            <label class="form-label small text-muted">Uploader le cahier (.pdf / .docx)</label>
            <input type="file" class="form-control mb-2" (change)="onFileSelected($event, c)">
            <button
              class="btn btn-primary btn-sm"
              (click)="uploadCahier(c)"
              [disabled]="uploadingId === c.id"
            >
              <ng-container *ngIf="uploadingId !== c.id; else uploading">
                <i class="bi bi-cloud-upload me-1"></i> Envoyer
              </ng-container>
              <ng-template #uploading>
                <span class="spinner-border spinner-border-sm"></span> Upload...
              </ng-template>
            </button>
          </div>
        </ng-template>
      </div>
    </div>
  </div>

  <ng-template #noClasses>
    <div class="alert alert-info text-center">Aucune classe trouvée pour ce professeur.</div>
  </ng-template>
</div>
